def page(filename,title,description,body,extra=''):
    html=f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="description" content="{escape(description,quote=True)}"><meta name="theme-color" content="#0a0908"><meta property="og:title" content="{escape(title,quote=True)}"><meta property="og:description" content="{escape(description,quote=True)}">
<title>{escape(title)}</title><link rel="icon" type="image/png" href="assets/favicon.png"><link rel="preload" href="assets/fonts/space-grotesk-latin.woff2" as="font" type="font/woff2" crossorigin>
<link rel="stylesheet" href="styles.css"><link rel="stylesheet" href="site-enhancements.css"><link rel="stylesheet" href="experience.css"><link rel="stylesheet" href="research.css">
<script defer src="site-content.js"></script><script defer src="app.js"></script><script defer src="experience.js"></script></head>
<body data-page="{filename[:-5]}">{ICONS}{header(filename)}<main id="main">{body}</main>{footer()}{extra}
<noscript><p class="noscript-note">The project pages and letters work without JavaScript. Enable it to use the animated signal selector, photo viewer and score examples.</p></noscript></body></html>'''
    (ROOT/filename).write_text(html,encoding='utf-8')
    print('wrote',filename,len(html))

