def research_card(source):
    """Render a source with an accessible clipping and independently attributed link."""
    s={key:escape(str(value),quote=True) for key,value in source.items()}
    clip_label=escape(f"View the supplied {source['publisher']} clipping: {source['original_title']} (opens in a new tab)",quote=True)
    article_label=escape(f"{source['link_text']}: {source['original_title']} on {source['publisher']} (opens in a new tab)",quote=True)
    original=''
    if source.get('original_url'):
        original=f'''<a class="research-original-link" href="{s['original_url']}" target="_blank" rel="noopener noreferrer" aria-label="Open the original Indian Express report (opens in a new tab)">{s['original_link_text']} {diag}</a>'''
    return f'''<article class="research-card" id="source-{s['number']}">
      <div class="research-card-top"><span>{s['number']} / {s['kind']}</span><span>{s['topic']}</span></div>
      <a class="research-clip" href="{s['image']}" target="_blank" rel="noopener noreferrer" aria-label="{clip_label}"><img src="{s['image']}" width="{s['image_width']}" height="{s['image_height']}" loading="lazy" alt=""><span>SUPPLIED CLIPPING <b aria-hidden="true">VIEW ↗</b></span></a>
      <div class="research-card-body"><div class="research-card-meta"><strong>{s['publisher']}</strong><time datetime="{s['date_iso']}">{s['date']}</time></div><h3>{s['title']}</h3><p>{s['summary']}</p><p class="research-credit">{s['credit']}</p>
      <details class="research-source-title"><summary>Original title <span aria-hidden="true">+</span></summary><p><cite>{s['original_title']}</cite></p></details>
      <div class="research-card-links"><a class="research-read" href="{s['url']}" target="_blank" rel="noopener noreferrer" aria-label="{article_label}">{s['link_text']} {diag}</a>{original}</div></div></article>'''

research_cards=''.join(research_card(source) for source in RESEARCH_SOURCES)
